 public static void main(String[]a)throws Exception {var urls=new ArrayList<java.net.URL>();urls.add(Path.of(a[1]).toUri().toURL());try(var libs=Files.list(Path.of(System.getProperty("user.dir"),"lib"))){for(var p:libs.filter(p->p.toString().endsWith(".jar")).toList())urls.add(p.toUri().toURL());}hierarchy=new java.net.URLClassLoader(urls.toArray(java.net.URL[]::new),ClassLoader.getPlatformClassLoader());try(var j=new JarFile(a[1])){for(var name:TYPES){var c=read(j,name);patch(c);byte[] b=bytes(c,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,b);}else try(var z=new JarFile(a[2])){if(!Arrays.equals(b,bytes(read(z,name),false)))throw new AssertionError(name);}}}System.out.println("PASS bounded static type2 route, retirement ports and original native constructor-core regeneration");}
